# EvoLink one-command API setup for Claude Code and Codex (Windows PowerShell 5.1+ / PowerShell 7): evolink-config, version 0.5.0
#
#   irm https://cdn.evolink.ai/cli/setup.ps1 | iex
#   & ([scriptblock]::Create((irm https://cdn.evolink.ai/cli/setup.ps1))) --model claude-sonnet-5-5
#   & ([scriptblock]::Create((irm https://cdn.evolink.ai/cli/setup.ps1))) codex
#   & ([scriptblock]::Create((irm https://cdn.evolink.ai/cli/setup.ps1))) doctor
#
# What it does: finds Node.js (18+; offers winget if missing), saves evolink-config to
# %USERPROFILE%\.evolink\cli, adds %USERPROFILE%\.evolink\bin\evolink-config.cmd, then runs `evolink-config setup`.
# It does not change PATH. This file is ASCII only; Chinese text is base64 so any download
# encoding works. The tool is embedded as base64 and checked against its SHA-256 before it runs.

function Invoke-EvoLinkSetup {
    param([Parameter(ValueFromRemainingArguments = $true)][string[]]$CliArgs)
    $ErrorActionPreference = 'Stop'
    $version = '0.5.0'
    $expectedSha = '1a4630d633810cadba03331873f3da46a74f0322bf0fc787df7bb019bf1ca1a0'
    $zh = ((Get-UICulture).Name -like 'zh*') -or ((Get-Culture).Name -like 'zh*')
    function T([string]$zhB64, [string]$en) {
        if ($zh) { return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($zhB64)) }
        return $en
    }
    function Say([string]$zhB64, [string]$en) { Write-Host (T $zhB64 $en) }

    # 1. Node.js 18+
    function Find-Node {
        $candidates = @()
        $cmd = Get-Command node.exe -ErrorAction SilentlyContinue
        if ($cmd) { $candidates += $cmd.Source }
        $candidates += @("$env:ProgramFiles\nodejs\node.exe", "$env:LOCALAPPDATA\Programs\nodejs\node.exe")
        if (${env:ProgramFiles(x86)}) { $candidates += "${env:ProgramFiles(x86)}\nodejs\node.exe" }
        foreach ($p in $candidates) {
            if ($p -and (Test-Path $p)) {
                $major = & $p -p "process.versions.node.split('.')[0]" 2>$null
                if ([int]$major -ge 18) { return $p }
            }
        }
        return $null
    }
    $node = Find-Node
    if (-not $node) {
        Say '5rKh5pyJ5om+5YiwIE5vZGUuanMgMTgg5oiW5pu06auY54mI5pys77yIQ2xhdWRlIENvZGUg6ZyA6KaBIE5vZGUuanMgMjIr77yJ44CC' 'Node.js 18+ was not found (Claude Code itself wants Node.js 22+).'
        if (Get-Command winget.exe -ErrorAction SilentlyContinue) {
            $ans = Read-Host (T '546w5Zyo55SoIHdpbmdldCDlronoo4UgTm9kZS5qcyBMVFMg5ZCX77yfW1kvbl0=' 'Install Node.js LTS with winget now? [Y/n]')
            if ($ans -eq '' -or $ans -match '^[Yy]') {
                winget install --id OpenJS.NodeJS.LTS -e --accept-package-agreements --accept-source-agreements
                $env:Path = [Environment]::GetEnvironmentVariable('Path', 'Machine') + ';' + [Environment]::GetEnvironmentVariable('Path', 'User')
                $node = Find-Node
            }
        }
        if (-not $node) {
            Say '6K+35YWI5a6J6KOFIE5vZGUuanMgMjLvvIzlho3ph43mlrDov5DooYzov5nmnaHlkb3ku6TvvJo=' 'Install Node.js 22, then run this command again:'
            Say 'ICDkuK3lm73lpKfpmYbvvJpodHRwczovL25wbW1pcnJvci5jb20vbWlycm9ycy9ub2RlLyDvvIjpgInmnIDmlrDnmoQgdjIyIOeahCAubXNpIOWuieijheWMhe+8iQ==' '  Mainland China mirror: https://npmmirror.com/mirrors/node/'
            Say 'ICDlrpjnvZHvvJpodHRwczovL25vZGVqcy5vcmcvemgtY24vZG93bmxvYWQ=' '  Official: https://nodejs.org/en/download'
            $global:LASTEXITCODE = 3
            return
        }
    }

    # 2. Save the CLI and a launcher under %USERPROFILE%\.evolink
    $homeDir = if ($env:EVOLINK_HOME) { $env:EVOLINK_HOME } else { Join-Path $env:USERPROFILE '.evolink' }
    $cliDir = Join-Path $homeDir 'cli'
    $binDir = Join-Path $homeDir 'bin'
    New-Item -ItemType Directory -Force -Path $cliDir, $binDir | Out-Null
    $cliPath = Join-Path $cliDir 'evolink.mjs'
    $cliB64 = @'
