'@
    $bytes = [Convert]::FromBase64String(($cliB64 -replace '\s', ''))
    $sha = [Security.Cryptography.SHA256]::Create()
    $actual = -join ($sha.ComputeHash($bytes) | ForEach-Object { $_.ToString('x2') })
    if ($actual -ne $expectedSha) {
        Say '5LiL6L2955qE6ISa5pys5LiN5a6M5pW077yI5qCh6aqM5aSx6LSl77yJ77yM6K+36YeN5paw6L+Q6KGM44CC' 'The downloaded script is incomplete (checksum mismatch); please run it again.'
        $global:LASTEXITCODE = 1
        return
    }
    [IO.File]::WriteAllBytes($cliPath, $bytes)
    # Up to 0.4.0 the launcher was called evolink.cmd; "evolink" is now the name of a different tool (the media CLI
    # on npm). Take that launcher away, but only when it is the one this script wrote.
    $oldLauncher = Join-Path $binDir 'evolink.cmd'
    if ((Test-Path $oldLauncher) -and ((Get-Content -Raw -Path $oldLauncher) -match 'EvoLink CLI launcher')) {
        Remove-Item -Force -Path $oldLauncher
    }
    $launcher = Join-Path $binDir 'evolink-config.cmd'
    $launcherText = "@echo off`r`nrem evolink-config launcher (version $version)`r`n`"$node`" `"$cliPath`" %*`r`n"
    [IO.File]::WriteAllText($launcher, $launcherText, (New-Object Text.UTF8Encoding $false))

    # 3. Run it (commands: setup / doctor / reset; setup when omitted)
    $known = @('setup', 'doctor', 'reset', 'help', '--help', '-h', '--version', '-v')
    if (-not $CliArgs -or $known -notcontains $CliArgs[0]) { $CliArgs = @('setup') + @($CliArgs | Where-Object { $_ }) }
    $shown = $launcher
    if ($launcher.StartsWith($env:USERPROFILE)) { $shown = '$env:USERPROFILE' + $launcher.Substring($env:USERPROFILE.Length) }
    $env:EVOLINK_CMD = "& `"$shown`""
    try {
        & $node $cliPath @CliArgs
    }
    finally {
        Remove-Item Env:EVOLINK_CMD -ErrorAction SilentlyContinue
    }
}

Invoke-EvoLinkSetup @args
